<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Preorder extends Model{protected $fillable=['product_id','open_at','close_at','status','closed_manually_at'];protected function casts():array{return['open_at'=>'datetime','close_at'=>'datetime','closed_manually_at'=>'datetime'];}public function product(){return $this->belongsTo(Product::class);}public function isOpen():bool{return $this->status==='open'&&(!$this->open_at||now()->gte($this->open_at))&&(!$this->close_at||now()->lt($this->close_at));}}
